package com.mamtrex.hospital.medication;
import com.mamtrex.hospital.audit.AuditService; import com.mamtrex.hospital.shared.NotFoundException; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/medication-orders") public class MedicationOrderController { private final MedicationOrderRepository repo; private final AuditService audit; public MedicationOrderController(MedicationOrderRepository r,AuditService a){repo=r;audit=a;} public record Request(@jakarta.validation.constraints.NotBlank String patientId, @jakarta.validation.constraints.NotBlank String drugId, @jakarta.validation.constraints.NotBlank String dose, @jakarta.validation.constraints.NotBlank String route, @jakarta.validation.constraints.NotBlank String frequency){} @PostMapping public MedicationOrder create(@Valid @RequestBody Request r){var e=repo.save(new MedicationOrder(r.patientId(), r.drugId(), r.dose(), r.route(), r.frequency()));audit.record("CREATE","MedicationOrder",e.getId().toString(),"created");return e;} @GetMapping public List<MedicationOrder> list(){return repo.findAll();} @GetMapping("/{id}") public MedicationOrder get(@PathVariable UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("MedicationOrder not found: "+id));} @DeleteMapping("/{id}") public void delete(@PathVariable UUID id){if(!repo.existsById(id))throw new NotFoundException("MedicationOrder not found: "+id);repo.deleteById(id);audit.record("DELETE","MedicationOrder",id.toString(),"deleted");} }
